import '@xyflow/react/dist/style.css';
import { Activity, ArrowDownToLine, ArrowLeft, ArrowRight, BookOpen, Check, CheckCircle2, ChevronDown, ChevronRight, Clock3, Code2, Copy, Download, FilePlus2, GitBranch, History, Keyboard, LayoutDashboard, LayoutGrid, LoaderCircle, Maximize2, MoreHorizontal, PanelBottom, Play, Plus, Power, Redo2, Save, Search, Settings2, Sparkles, Square, Trash2, Undo2, Upload, Workflow, X } from 'lucide-react';
