  const exportWorkflow = () => { try { const payload = parsedDocument(); const url = URL.createObjectURL(new Blob([pretty(payload)], { type: 'application/json' })); const anchor = window.document.createElement('a'); anchor.href = url; anchor.download = `${payload.name.replace(/[^a-z0-9]+/gi, '-').toLowerCase()}.json`; anchor.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); setMessage('Workflow exported'); } catch (err) { setError((err as Error).message); } };
  const importWorkflow = () => perform(async () => {
    const imported = parseJson(importText, 'Workflow import') as WorkflowDocument;
    if (!imported || typeof imported.name !== 'string' || !Array.isArray(imported.nodes) || !Array.isArray(imported.edges)) throw new Error('A workflow file needs a name, nodes, and edges');
    const validation = await api<{ valid: boolean; errors: string[] }>('/workflows/validate', { method: 'POST', body: JSON.stringify(imported) });
    if (!validation.valid) throw new Error(validation.errors.join('; '));
    if (dirty && (undoStack.length > 0 || Object.keys(drafts).length > 0) && !window.confirm('Replace your unsaved changes with the imported workflow?')) return;
    const next = remapWorkflow(imported);
    setUndoStack([]); setRedoStack([]); selectDocument(next); setSavedSignature(''); setModal(null); window.history.replaceState(null, '', '/'); setMessage('Workflow imported as a new draft');
  });
  const chooseRecipe = (kind: string) => { if (dirty && (undoStack.length > 0 || Object.keys(drafts).length > 0) && !window.confirm('Replace your unsaved changes with this workflow?')) return; setUndoStack([]); setRedoStack([]); selectDocument(createRecipe(kind)); setSavedSignature(''); setModal(null); setPanel('input'); setPanelOpen(true); window.history.replaceState(null, '', '/'); setMessage(kind === 'blank' ? 'Fresh canvas ready. Add your first action.' : 'Recipe loaded. Run it with the example input or make it your own.'); };
  const previewNode = () => perform(async () => { if (!selectedNode) return; const next = applyDrafts().nodes.find((node) => node.id === selected)!; const input = parseJson(testInput, 'Test input'); const variables: Record<string, unknown> = {}; for (const event of execution?.events ?? []) { if (event.type === 'node.started' && event.nodeId === selected) break; if (event.type === 'node.completed' && event.nodeId) variables[event.nodeId] = event.data; } const result = await api<{ data: unknown; branch?: string }>(`/nodes/${next.type}/preview`, { method: 'POST', body: JSON.stringify({ config: next.config, input, variables }) }); setPreview({ nodeId: selected, input, data: result.data, branch: result.branch }); setInspectorTab('data'); setMessage('Node preview complete. No workflow execution was created.'); });
